// Base case: if tree is empty, create new node
    if (root == nullptr) {
        root = new TreeNode(item);
        return;
    }

    // BST insertion
    if (item < root->data) {
        avlInsert(root->left, item);
    } else if (item > root->data) {
        avlInsert(root->right, item);
    } else {
        // Duplicate, don't insert
        return;
    }

    // Update height
    root->height = 1 + std::max(getHeight(root->left), getHeight(root->right));

    // Get balance factor
    int balance = getBalance(root);

    // Left Left Case
    if (balance > 1 && item < root->left->data) {
        avlRotateRight(root);
    }
    // Right Right Case
    else if (balance < -1 && item > root->right->data) {
        avlRotateLeft(root);
    }
    // Left Right Case
    else if (balance > 1 && item > root->left->data) {
        avlRotateLeft(root->left);
        avlRotateRight(root);
    }
    // Right Left Case
    else if (balance < -1 && item < root->right->data) {
        avlRotateRight(root->right);
        avlRotateLeft(root);
    }

